import{c,$ as d,Q as s,j as r,g as e,n as l,o,m as n}from"./chunks/framework.CWBTDBPu.js";const x=JSON.parse('{"title":"YuTeleport 权限节点","description":"","frontmatter":{"title":"YuTeleport 权限节点"},"headers":[],"relativePath":"plugins/items/yu-teleport/permissions.md","filePath":"plugins/items/yu-teleport/permissions.md"}'),i={name:"plugins/items/yu-teleport/permissions.md"},h={class:"quick-actions"};function u(b,t,y,m,g,k){const a=d("CopyMarkdownButton"),p=d("CopyLLMButton");return s(),r("div",null,[t[0]||(t[0]=e("h1",{id:"yuteleport-权限节点",tabindex:"-1"},[l("YuTeleport 权限节点 "),e("a",{class:"header-anchor",href:"#yuteleport-权限节点","aria-label":'Permalink to "YuTeleport 权限节点"'},"​")],-1)),e("div",h,[o(a,{page:""}),o(p,{page:""})]),t[1]||(t[1]=n(`<h2 id="权限总览" tabindex="-1">权限总览 <a class="header-anchor" href="#权限总览" aria-label="Permalink to &quot;权限总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yuteleport.admin</code></td><td><code>op</code></td><td>管理权限集合，包含随机传送、重载、warp、home、tpa、back、分享和绕过权限。</td></tr><tr><td><code>yuteleport.use</code></td><td><code>true</code></td><td>允许使用 <code>/yuteleport</code>、<code>/ytp</code>、<code>/rtp</code> 随机传送。目标玩家自助或被代传送时都需要该权限。</td></tr><tr><td><code>yuteleport.biome</code></td><td><code>op</code></td><td>允许使用 <code>biome:&lt;模式&gt;</code> 指定单次随机传送的目标生物群系。</td></tr><tr><td><code>yuteleport.teleport.others</code></td><td><code>op</code></td><td>允许用 <code>/yuteleport &lt;玩家&gt; [世界]</code> 随机传送其他玩家。</td></tr><tr><td><code>yuteleport.reload</code></td><td><code>op</code></td><td>允许执行 <code>/yuteleport reload</code>。</td></tr><tr><td><code>yuteleport.share</code></td><td><code>true</code></td><td>允许分享传送成功后的当前位置。</td></tr><tr><td><code>yuteleport.bypass.cooldown</code></td><td><code>op</code></td><td>跳过随机传送、warp、home、tpa、back 和分享冷却。</td></tr><tr><td><code>yuteleport.bypass.cooldown.others</code></td><td><code>op</code></td><td>管理员代传送其他玩家时无视目标玩家冷却。</td></tr><tr><td><code>yuteleport.bypass.cost</code></td><td><code>op</code></td><td>跳过随机传送、warp、home、tpa、back 和分享费用。</td></tr><tr><td><code>yuteleport.bypass.wait</code></td><td><code>op</code></td><td>跳过随机传送、warp、home、tpa、back 等待时间。</td></tr></tbody></table><h2 id="warp-权限" tabindex="-1">Warp 权限 <a class="header-anchor" href="#warp-权限" aria-label="Permalink to &quot;Warp 权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yuteleport.warp.use</code></td><td><code>true</code></td><td>允许使用 <code>/warp</code> 查看和传送可见 warp。</td></tr><tr><td><code>yuteleport.warp.set</code></td><td><code>true</code></td><td>允许使用 <code>/setwarp</code> 创建或更新 warp。</td></tr><tr><td><code>yuteleport.warp.delete</code></td><td><code>true</code></td><td>允许删除自己的 warp。</td></tr><tr><td><code>yuteleport.warp.public</code></td><td><code>true</code></td><td>允许公开或取消公开自己的 warp。</td></tr><tr><td><code>yuteleport.warp.admin</code></td><td><code>op</code></td><td>允许编辑、删除所有玩家的 warp。</td></tr><tr><td><code>yuteleport.warp.limit.bypass</code></td><td><code>op</code></td><td>允许无视 warp 数量过期锁定。</td></tr><tr><td><code>yuteleport.warps.*</code></td><td><code>op</code></td><td>允许使用所有 restricted warp。</td></tr><tr><td><code>yuteleport.warps.&lt;名称&gt;</code></td><td><code>false</code></td><td>允许使用指定 restricted warp。</td></tr><tr><td><code>yuteleport.warp.limit.&lt;数量&gt;</code></td><td><code>false</code></td><td>动态提高可创建 warp 数量，例如 <code>yuteleport.warp.limit.25</code>。</td></tr><tr><td><code>yuteleport.warp.limit.unlimited</code></td><td><code>false</code></td><td>不限制可创建 warp 数量。</td></tr></tbody></table><h2 id="home-权限" tabindex="-1">Home 权限 <a class="header-anchor" href="#home-权限" aria-label="Permalink to &quot;Home 权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yuteleport.home.use</code></td><td><code>true</code></td><td>允许使用 home 传送和查看自己的 home。</td></tr><tr><td><code>yuteleport.home.set</code></td><td><code>true</code></td><td>允许设置或更新 home。</td></tr><tr><td><code>yuteleport.home.delete</code></td><td><code>true</code></td><td>允许删除 home。</td></tr><tr><td><code>yuteleport.home.others</code></td><td><code>op</code></td><td>允许查看或使用在线玩家的 home，也可用管理语法删除在线玩家 home。</td></tr><tr><td><code>yuteleport.home.public</code></td><td><code>true</code></td><td>允许公开或取消公开自己的 home。</td></tr><tr><td><code>yuteleport.home.limit.bypass</code></td><td><code>op</code></td><td>允许无视 home 数量过期锁定。</td></tr><tr><td><code>yuteleport.home.limit.&lt;数量&gt;</code></td><td><code>false</code></td><td>动态提高可拥有 home 数量，例如 <code>yuteleport.home.limit.25</code>。</td></tr><tr><td><code>yuteleport.home.limit.unlimited</code></td><td><code>false</code></td><td>不限制可拥有 home 数量。</td></tr></tbody></table><h2 id="tpa-权限" tabindex="-1">TPA 权限 <a class="header-anchor" href="#tpa-权限" aria-label="Permalink to &quot;TPA 权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yuteleport.tpa.use</code></td><td><code>true</code></td><td>允许使用 <code>/tpa</code>、<code>/tpaccept</code>、<code>/tpdeny</code>、<code>/tpacancel</code>。</td></tr><tr><td><code>yuteleport.tpa.here</code></td><td><code>true</code></td><td>允许使用 <code>/tpahere</code>。</td></tr><tr><td><code>yuteleport.tpa.ignore</code></td><td><code>true</code></td><td>允许忽略发给自己的 TPA 请求。</td></tr><tr><td><code>yuteleport.tpa.all</code></td><td><code>op</code></td><td>允许向全服玩家发送 tpahere 请求。</td></tr></tbody></table><h2 id="back-权限" tabindex="-1">Back 权限 <a class="header-anchor" href="#back-权限" aria-label="Permalink to &quot;Back 权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>yuteleport.back.*</code></td><td><code>op</code></td><td><code>/back</code> 权限集合，包含使用、死亡点、清空和管理权限。</td></tr><tr><td><code>yuteleport.back.use</code></td><td><code>true</code></td><td>允许使用 <code>/back</code>、<code>/back list</code> 和点击历史条目返回。</td></tr><tr><td><code>yuteleport.back.death</code></td><td><code>true</code></td><td>允许使用 <code>/back death</code>，并允许在历史列表和无参数 <code>/back</code> 中访问死亡记录。</td></tr><tr><td><code>yuteleport.back.clear</code></td><td><code>true</code></td><td>允许执行 <code>/back clear</code> 清空自己的 back 历史。</td></tr><tr><td><code>yuteleport.back.admin</code></td><td><code>op</code></td><td>管理类 <code>/back</code> 权限节点，供权限组归类和后续管理能力使用。</td></tr></tbody></table><h2 id="权限组" tabindex="-1">权限组 <a class="header-anchor" href="#权限组" aria-label="Permalink to &quot;权限组&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport.group.&lt;组名&gt;</span></span></code></pre></div><p>该权限用于匹配 <code>config.yml</code> 中的 <code>groups.&lt;组名&gt;</code>。玩家同时命中多个组时，使用配置中靠前的组。</p><h2 id="普通玩家组" tabindex="-1">普通玩家组 <a class="header-anchor" href="#普通玩家组" aria-label="Permalink to &quot;普通玩家组&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport.use</span></span>
<span class="line"><span>yuteleport.warp.use</span></span>
<span class="line"><span>yuteleport.warp.set</span></span>
<span class="line"><span>yuteleport.warp.delete</span></span>
<span class="line"><span>yuteleport.home.use</span></span>
<span class="line"><span>yuteleport.home.set</span></span>
<span class="line"><span>yuteleport.home.delete</span></span>
<span class="line"><span>yuteleport.tpa.use</span></span>
<span class="line"><span>yuteleport.tpa.here</span></span>
<span class="line"><span>yuteleport.tpa.ignore</span></span>
<span class="line"><span>yuteleport.back.use</span></span>
<span class="line"><span>yuteleport.back.death</span></span>
<span class="line"><span>yuteleport.back.clear</span></span>
<span class="line"><span>yuteleport.share</span></span></code></pre></div><p>适合普通生存服玩家。世界可用性应优先通过 <code>teleports.defaults.world-access</code> 控制，而不是只依赖权限。</p><h2 id="vip-或赞助组" tabindex="-1">VIP 或赞助组 <a class="header-anchor" href="#vip-或赞助组" aria-label="Permalink to &quot;VIP 或赞助组&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport.group.vip</span></span>
<span class="line"><span>yuteleport.bypass.cooldown</span></span></code></pre></div><p>如果希望 VIP 不受等待限制，额外给予：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport.bypass.wait</span></span></code></pre></div><p>如果希望 VIP 免扣费，额外给予：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport.bypass.cost</span></span></code></pre></div><p>如果希望 VIP 获得更多数量上限，可使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport.warp.limit.25</span></span>
<span class="line"><span>yuteleport.home.limit.25</span></span></code></pre></div><h2 id="管理员组" tabindex="-1">管理员组 <a class="header-anchor" href="#管理员组" aria-label="Permalink to &quot;管理员组&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport.admin</span></span></code></pre></div><p><code>yuteleport.admin</code> 已包含常用管理权限。若不想给完整管理权限，可拆分给予 <code>yuteleport.reload</code>、<code>yuteleport.teleport.others</code>、<code>yuteleport.warp.admin</code>、<code>yuteleport.home.others</code>、<code>yuteleport.tpa.all</code>、<code>yuteleport.back.admin</code>。</p><h2 id="控制台与命令方块" tabindex="-1">控制台与命令方块 <a class="header-anchor" href="#控制台与命令方块" aria-label="Permalink to &quot;控制台与命令方块&quot;">​</a></h2><p>控制台没有玩家位置，不能执行无参数 <code>/yuteleport</code>、<code>/ytp</code> 或 <code>/rtp</code>。控制台可使用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yuteleport &lt;玩家&gt;</span></span>
<span class="line"><span>yuteleport &lt;玩家&gt; &lt;世界&gt;</span></span>
<span class="line"><span>yuteleport reload</span></span></code></pre></div><p>控制台权限由服务端命令系统处理，通常不需要额外配置权限插件。</p>`,31))])}const w=c(i,[["render",u]]);export{x as __pageData,w as default};
